            elif key == 'Needs':
                for t in value_tokens:
                    directives[canonical_name]['Needs'].add(canonical[t])
            elif key == 'Requires':
                for t in value_tokens:
                    directives[canonical_name]['Requires'].add(canonical[t])
            elif key == 'Alias':
                for t in value_tokens:
                    directives[canonical_name]['Alias'].add(canonical[t])
            elif key == 'Phony':
                directives[canonical_name]['Phony'] = value_tokens[0]

    # Default Phony to 'no' if not specified
    for name in universe:
        if directives[name]['Phony'] is None:
            directives[name]['Phony'] = 'no'

    # Phase 5: Dependency Graph Construction
    graph = defaultdict(set)
    all_nodes = list(universe)

    for name in all_nodes:
        deps = directives[name]['Depends']
        for d in deps:
            graph[d].add(name)
        # Before = Y1 Y2 ... → edges: U → Y1, U → Y2
        before = directives[name]['Before']
        for b in before:
            graph[name].add(b)
        # After = Z1 Z2 ... → edges: Z1 → U, Z2 → U
        after = directives[name]['After']
        for a in after:
            graph[a].add(name)
        # Needs = W1 W2 ... → edges: U → W1, U → W2
        needs = directives[name]['Needs']
        for n in needs:
            graph[name].add(n)
        # Requires = V1 V2 ... → edges: U → V1, U → V2
        requires = directives[name]['Requires']
        for r in requires:
            graph[name].add(r)

    # Phase 6: Cycle Detection (SCC)
    index_counter = [0]
    stack = []
    lowlink = {}
    index = {}
    on_stack = {}
    sccs = []

    def strongconnect(v):
        index[v] = index_counter[0]
        lowlink[v] = index_counter[0]
        index_counter[0] += 1
        stack.append(v)
        on_stack[v] = True

        for w in graph[v]:
            if w not in index:
                strongconnect(w)
                lowlink[v] = min(lowlink[v], lowlink[w])
            elif on_stack.get(w, False):
                lowlink[v] = min(lowlink[v], index[w])

        if lowlink[v] == index[v]:
            scc = []
            while True:
                w = stack.pop()
                on_stack[w] = False
                scc.append(w)
                if w == v:
                    break
            sccs.append(scc)

    for v in all_nodes:
        if v not in index:
            strongconnect(v)

    # Phase 6: Determine which SCCs are cycles
    cycles = []
    for scc in sccs:
        scc_sorted = sorted(scc)
        if len(scc) >= 2:
            cycles.append(scc_sorted)
        elif len(scc) == 1:
            node = scc_sorted[0]
            if node in graph[node]:
                cycles.append(scc_sorted)

    cycles.sort()

    # Phase 7: Topological Ordering
    # Build condensation DAG
    node_to_comp = {}
    comp_to_nodes = {}
    comp_id = 0
    for scc in sccs:
        for node in scc:
            node_to_comp[node] = comp_id
        comp_to_nodes[comp_id] = sorted(scc)
        comp_id += 1

    comp_graph = defaultdict(set)
    comp_in_degree = defaultdict(int)

    for v in all_nodes:
        for w in graph[v]:
            if node_to_comp[v] != node_to_comp[w]:
                if w not in comp_graph[node_to_comp[v]]:
                    comp_graph[node_to_comp[v]].add(node_to_comp[w])
                    comp_in_degree[node_to_comp[w]] += 1

    # Kahn's algorithm with deterministic tie-breaking
    comp_list = []
    for i in range(len(comp_to_nodes)):
        comp_list.append((comp_to_nodes[i][0], comp_to_nodes[i]))

    comp_list.sort(key=lambda x: x[0])

    queue = []
    for i in range(len(comp_to_nodes)):
        if comp_in_degree[i] == 0:
            queue.append(i)
    queue.sort()

    order = []
    while queue:
        current_comp = queue.pop(0)
        order.extend(comp_to_nodes[current_comp])

        for neighbor in comp_graph[current_comp]:
            comp_in_degree[neighbor] -= 1
            if comp_in_degree[neighbor] == 0:
                queue.append(neighbor)
        queue.sort()

    # Phase 8: Output
    result = {
        "order": order,
        "cycles": cycles
    }

    return json.dumps(result, separators=(',', ':'))
EOF"}
